    "noi_dung_giang": "- Cập nhật mới quy định của pháp luật và Agribank về PCRT và TTKB\n- Hoạt động PCRT trong hệ thống Agribank; Trách nhiệm trong việc thực hiện tuân thủ quy định pháp luật và quy định nội bộ về PCRT, quy định về xử phạt hành chính... (Nghị định 88/2019/NĐ-CP, Nghị định 143/2021/NĐ-CP...)\n- Hướng dẫn về các phần mềm hỗ trợ công tác PCRT và TTKB tại Agribank.\n- Phương thức, thủ đoạn rửa tiền; rủi ro về rửa tiền liên quan đến sản phẩm dịch vụ, nghiệp vụ ngân hàng.\n- Các tình huống, kinh nghiệm thực tế, kỹ năng thực hiện công tác PCRT tại Agribank (ứng xử với một số tình huống nghi ngờ)...",
